#!/usr/bin/env Rscript
options(warn=2); args<-commandArgs(trailingOnly=TRUE); if(length(args)!=4L) stop("usage: build_mv17e_h2_qualification_closure.R <prefreeze> <primary> <repeat> <output>")
p<-normalizePath(args[[1]],mustWork=TRUE); a<-normalizePath(args[[2]],mustWork=TRUE); b<-normalizePath(args[[3]],mustWork=TRUE); o<-args[[4]]; if(dir.exists(o)) stop("MV17-E closure exists"); dir.create(o,recursive=TRUE)
source("R/mv08z_landscape_production.R"); r<-.mv08z_read_csv; w<-.mv08z_atomic_csv; h<-.mv08z_sha256_file
